// "Dirge": played once as the cemetery begins, on two SIDs of the Commodore 64 (reSID, MOS 6581), rendered by tools/music, as Ogg Vorbis in base64
// so that the page can decode it and loop it without a gap, even when opened as a file.
window.MUSIC = window.MUSIC || {};
window.MUSIC.dirge = "";
window.MUSIC_ONCE = window.MUSIC_ONCE || {};
window.MUSIC_ONCE.dirge = 25.6000;
